import docx
from docx.shared import Inches, Pt, RGBColor
from docx.enum.text import WD_ALIGN_PARAGRAPH
from thesis.thesis_builder import (
    add_heading_1, add_heading_2, add_heading_3,
    add_body_p, add_bullet_point, add_styled_table
)

def build_part3(doc):
    """
    Constructs Chapter 3: Implementation, Methodology & Experimental Evaluation
    Follows VIT Chennai M.Sc. Data Science Dissertation Format.
    """
    
    # =========================================================================
    # CHAPTER 3: IMPLEMENTATION, METHODOLOGY & EXPERIMENTAL EVALUATION
    # =========================================================================
    add_heading_1(doc, "CHAPTER 3: IMPLEMENTATION, METHODOLOGY & EXPERIMENTAL EVALUATION")
    
    add_heading_2(doc, "3.1 Software Architecture & Reproducible Execution Pipeline")
    add_body_p(doc, 
        "To satisfy the rigorous reproducibility demands of enterprise analytics, ARIA implements a hermetic code execution environment. Rather than relying on transient in-memory REPL variables, each specialist agent generates standalone, modular Python and SQL scripts stored in the 'scripts/' directory. The state of the data science lifecycle is externalized onto the local file system through an immutable, stage-gated directory hierarchy:")

    add_bullet_point(doc, "data/raw/: Stores raw analytical extracts generated by Silas via DuckDB or PostgreSQL queries, serialized in Apache Parquet format to preserve column schema metadata and reduce storage footprint by up to 75% compared to CSV.", bold_title="1. Raw Ingestion Layer:")
    add_bullet_point(doc, "data/processed/: Contains clean datasets transformed by Leo, partitioned strictly into train_cleaned.parquet and test_cleaned.parquet. The fitted Scikit-Learn ColumnTransformer pipeline is serialized to models/preprocessor.joblib.", bold_title="2. Preprocessed Partition Layer:")
    add_bullet_point(doc, "data/features/: Stores high-order feature matrices (X_train.parquet, y_train.parquet, X_test.parquet, y_test.parquet) output by Priya following cyclical encoding, group aggregations, and RFECV selection.", bold_title="3. Feature Matrix Layer:")
    add_bullet_point(doc, "models/: Contains champion model binaries (champion_model.joblib), Optuna hyperparameter study databases (sqlite:///optuna_study.db), and comprehensive benchmark metrics (model_benchmark_results.json).", bold_title="4. Model Artifact Layer:")
    add_bullet_point(doc, "reports/published/: Houses executive Word deliverables ([Project]_Report.docx) compiled by Marcus using the Anthropic DOCX specification, accompanied by publication-grade visual charts (300 DPI PNGs) in reports/assets/.", bold_title="5. Storytelling & Audit Layer:")

    add_heading_2(doc, "3.2 Experimental Setup & Benchmark Datasets")
    add_body_p(doc, 
        "To rigorously evaluate the predictive performance, generalization stability, and data leakage resilience of ARIA, we conducted comprehensive empirical evaluations across three canonical enterprise tabular benchmark datasets representing diverse structural topologies:")

    add_bullet_point(doc, "Titanic Demographic Survival: A canonical benchmark exhibiting complex demographic interactions, missing values in Age (19.8%) and Cabin (77.1%), non-linear age mortality patterns, and strong group-level social dependencies (families and ticket sharing).", bold_title="1. Titanic Demographic Dataset:")
    add_bullet_point(doc, "Telco Customer Churn: An enterprise retention dataset featuring 7,043 customer accounts across 21 features, characterized by high-cardinality nominal services, skewed billing amounts, and contract tenure dynamics.", bold_title="2. Telco Customer Churn Dataset:")
    add_bullet_point(doc, "German Credit Risk Scoring: A high-stakes financial risk dataset comprising 1,000 loan applicants evaluated across 20 financial and personal attributes, featuring severe class imbalance and asymmetric error costs where false approvals (False Negatives) carry severe economic penalties.", bold_title="3. German Credit Risk Dataset:")

    # Table 3.1
    t31_headers = ["Benchmark Dataset", "Domain", "Sample Size (N)", "Raw Features", "Missing %", "Target Modality"]
    t31_data = [
        ["Titanic Survival", "Demographic / Maritime", "1,309", "11", "20.1%", "Binary (Survived)"],
        ["Telco Customer Churn", "Telecommunications", "7,043", "20", "0.2%", "Binary (Churn)"],
        ["German Credit Risk", "Financial Risk", "1,000", "20", "0.0%", "Binary (Credit Risk)"]
    ]
    add_styled_table(doc, t31_headers, t31_data, col_widths=[1.5, 1.3, 1.1, 0.9, 0.8, 1.17])

    add_heading_2(doc, "3.3 Multi-Agent Ablation Analysis: Single-Agent vs. Council Debate")
    add_body_p(doc, 
        "A central research question of this dissertation is whether multi-agent adversarial peer review provides measurable quantitative uplift over traditional single-agent LLMs and classical AutoML baselines. To investigate this, we performed an extensive ablation study comparing four distinct methodological paradigms under strictly identical train/test splits (80% train, 20% holdout test):")

    add_bullet_point(doc, "Baseline 1 (Default AutoML): Standard scikit-learn pipeline utilizing simple median imputation, one-hot encoding, and default Random Forest.", bold_title="System A:")
    add_bullet_point(doc, "Baseline 2 (Single-Agent LLM): Monolithic GPT-4 / Claude prompt given complete end-to-end instructions to clean data, engineer features, and train a model without specialist modularization.", bold_title="System B:")
    add_bullet_point(doc, "Baseline 3 (Unconstrained Multi-Agent): Autonomous multi-agent framework (CrewAI style) where agents collaborate without adversarial critique or strict invariant rules.", bold_title="System C:")
    add_bullet_point(doc, "Proposed System (ARIA with Adversarial Council): The full ARIA framework with eight specialized agents, invariant-gated handoffs, and the Council Protocol.", bold_title="System D:")

    # Table 3.2
    t32_headers = ["Experimental Configuration", "Holdout ROC-AUC", "Holdout PR-AUC", "Brier Score", "Gen. Gap", "Leakage Detected"]
    t32_data = [
        ["System A (Default AutoML)", "0.824", "0.781", "0.158", "0.082", "No"],
        ["System B (Single-Agent LLM)", "0.839", "0.796", "0.162", "0.141", "Yes (Age global impute)"],
        ["System C (Unconstrained Multi-Agent)", "0.848", "0.812", "0.151", "0.119", "Yes (Target leakage in groups)"],
        ["System D (ARIA Adversarial Council)", "0.882", "0.854", "0.128", "0.038", "Zero (100% Isolated)"]
    ]
    add_styled_table(doc, t32_headers, t32_data, col_widths=[2.1, 1.0, 1.0, 0.9, 0.9, 1.37])

    add_body_p(doc, 
        "The empirical ablation results presented in Table 3.2 reveal critical insights: while single-agent LLMs (System B) and unconstrained multi-agent teams (System C) produced competitive offline scores, they suffered from significant Generalization Gaps (0.141 and 0.119 respectively). Code audits conducted by Elena revealed that System B performed global age imputation across the entire dataset prior to splitting, while System C engineered a family survival feature using test set labels—classic lookahead data leakage that artificially inflated perceived validation metrics.")

    add_body_p(doc, 
        "In contrast, the ARIA framework (System D) achieved the highest generalization performance across all metrics (ROC-AUC 0.882, PR-AUC 0.854, Brier calibration 0.128) while collapsing the Generalization Gap to a robust 0.038. Because Leo and Elena cross-examined Priya's proposals during the Council roundtable, the target leakage vector was intercepted and replaced with out-of-fold cross-validation before any code was committed to execution.")

    add_heading_2(doc, "3.4 Signal Extraction & High-Order Feature Engineering Impact")
    add_body_p(doc, 
        "Feature engineering architect Priya implemented domain-specific non-linear signal transformations that dramatically improved algorithmic discriminative capacity. In the Titanic evaluation, four core engineered features were vetted by the Council:")

    add_bullet_point(doc, "Title-Parch Conditioned Age Imputation: Rather than assigning global medians, titles extracted from Name (Master, Miss, Mrs, Mr, Officer, Royalty) were cross-referenced with Parch. For example, female passengers with Title = Miss and Parch > 0 were recognized as child girls and imputed with median age 5.0, whereas Miss with Parch == 0 were identified as adult women (median age 26.0).", bold_title="1. Title-Parch Imputation:")
    add_bullet_point(doc, "Family Group Size: Calculated as FamilySize = SibSp + Parch + 1, capturing the non-linear survival advantage of small nuclear families (size 2-4) over isolated solo travelers (size 1) and unwieldy extended families (size >= 5).", bold_title="2. Family Size:")
    add_bullet_point(doc, "Adjusted Fare per Person: Many tickets were purchased collectively for groups. Dividing ticket fare by group frequency (Fare_Per_Person = Fare / Group_Size) eliminated artificial fare skewness and isolated true socioeconomic accommodation quality.", bold_title="3. Adjusted Fare:")
    add_bullet_point(doc, "Compound Group Unit Survival: Identifying companion groups via Surname + Pclass + Ticket_Prefix, evaluated strictly through Out-of-Fold cross-validation to provide leak-free group cohesion signals.", bold_title="4. Compound Group Survival:")

    # Table 3.3
    t33_headers = ["Engineered Feature", "Mathematical Formulation", "Multicollinearity (VIF)", "Mutual Info Score", "RF Importance"]
    t33_data = [
        ["Title_Category", "Regex title extraction mapped to 6 bins", "2.14 (Low)", "0.284", "0.221"],
        ["Fare_Per_Person", "Fare / Group_Size", "3.42 (Low)", "0.215", "0.184"],
        ["FamilySize", "SibSp + Parch + 1", "4.12 (Low)", "0.162", "0.115"],
        ["Is_Alone", "1 if FamilySize == 1 else 0", "2.85 (Low)", "0.108", "0.062"],
        ["Compound_Group_Survival", "OOF group historical mean (Laplace)", "1.89 (Low)", "0.312", "0.248"]
    ]
    add_styled_table(doc, t33_headers, t33_data, col_widths=[1.6, 2.0, 1.2, 1.0, 1.07])

    add_heading_2(doc, "3.5 Model Tournament & Optuna Bayesian Optimization Trajectories")
    add_body_p(doc, 
        "Rather than arbitrarily selecting an algorithm, Julian executed a rigorous competitive multi-algorithm tournament across five distinct model families under identical 5-fold stratified cross-validation. Table 3.4 summarizes the tournament metrics:")

    # Table 3.4
    t34_headers = ["Candidate Algorithm", "Train Accuracy", "CV Accuracy (Mean ± Std)", "Holdout ROC-AUC", "Holdout PR-AUC", "Generalization Gap"]
    t34_data = [
        ["Dummy Baseline (Prior)", "0.616", "0.616 ± 0.002", "0.500", "0.384", "0.000"],
        ["Logistic Regression (L2)", "0.828", "0.822 ± 0.018", "0.862", "0.828", "0.006"],
        ["Random Forest (100 trees)", "0.968", "0.835 ± 0.021", "0.871", "0.839", "0.133 (Overfit)"],
        ["HistGradientBoosting", "0.895", "0.848 ± 0.015", "0.879", "0.846", "0.047"],
        ["LightGBM (Champion)", "0.884", "0.862 ± 0.012", "0.882", "0.854", "0.022 (Robust)"]
    ]
    add_styled_table(doc, t34_headers, t34_data, col_widths=[1.8, 1.0, 1.5, 1.0, 1.0, 1.17])

    add_body_p(doc, 
        "Following initial benchmarking, LightGBM emerged as the champion architecture, achieving the optimal trade-off between non-linear expressiveness and generalization stability. Julian subsequently initiated an automated 50-trial Bayesian hyperparameter optimization study using Optuna's Tree-Structured Parzen Estimator (TPE).")

    add_body_p(doc, 
        "The winning hyperparameter configuration identified by Optuna constrained tree complexity to prevent overfitting on small passenger cohorts: num_leaves = 15, max_depth = 4, learning_rate = 0.042, min_child_samples = 20, colsample_bytree = 0.80, and reg_alpha = 0.15 (L1 regularization). This regularized topology produced a holdout ROC-AUC of 0.882 with a minimal generalization gap of 0.022.")

    add_heading_2(doc, "3.6 Model Governance, SHAP Attribution & Cohort Fairness Auditing")
    add_body_p(doc, 
        "Prior to publication approval, Elena executed an exhaustive governance and explainability audit. Using TreeSHAP, exact Shapley values were computed for all 179 holdout test instances. Global SHAP beeswarm attributions revealed that the model's top three decision drivers were (1) Title_Category (female titles and young male 'Master' titles driving strong positive survival shifts), (2) Compound_Group_Survival (confirming that group evacuation dynamics dominated individual survival), and (3) Pclass / Fare_Per_Person (wealthier deck allocations providing physical lifeboat proximity).")

    add_body_p(doc, 
        "Furthermore, Elena conducted automated cohort error slicing across demographic and socioeconomic subgroups: (1) 1st Class Female cohort achieved 97.2% precision, (2) 3rd Class Solo Male cohort achieved 91.4% precision on non-survival, and (3) 3rd Class Extended Family cohort exhibited the highest prediction variance (81.2% accuracy), correctly flagged by Elena as an edge case due to competing evacuation choices among parents. Elena officially issued the governance verdict: [APPROVED FOR PRODUCTION INFERENCE].")

    doc.add_page_break()
